  function run(sec, frameMs) { frameMs = frameMs || 16.667; var n = Math.round(sec * 1000 / frameMs); for (var i = 0; i < n; i++) step(frameMs); }
  var cd = document.getElementById('countdown');
  var sc = document.getElementById('scrubber');
  var tg = document.getElementById('btn-toggle');
  var rf = document.getElementById('btn-refire');
  var ip = document.getElementById('icon-pause'), ipl = document.getElementById('icon-play');
  var pills = Array.prototype.slice.call(document.querySelectorAll('.speed-pill'));
  function vis(el) { return getComputedStyle(el).display !== 'none'; }
  function snap(tag) { return tag + ': state=' + state + ' simTime=' + simTime.toFixed(3) + ' scrub=' + sc.value + ' cd=' + (vis(cd) ? ('"' + cd.textContent + '"') : 'hidden') + ' pause=' + vis(ip) + ' play=' + vis(ipl) + ' aria=' + tg.getAttribute('aria-label'); }
  try {
    __L('--- logic test start ---');
    check('initial: countdown visible "3" before first frame', vis(cd) && cd.textContent === '3', snap('init'));
    check('initial: scrubber "0"', sc.value === '0');
    step(16); // first rAF callback
    check('first frame: COUNTDOWN, "3"', state === 'COUNTDOWN' && cd.textContent === '3' && vis(cd), snap('f1'));
    run(0.9);
    check('t~0.9: still "3"', cd.textContent === '3' && state === 'COUNTDOWN', snap('0.9'));
    run(0.2);
    check('t~1.1: "2"', cd.textContent === '2' && vis(cd), snap('1.1'));
    run(0.9);
    check('t~2.0..2.1: "1"', cd.textContent === '1' && vis(cd), snap('2.0'));
    check('simTime stays 0 during countdown', simTime === 0 && sc.value === '0', snap('2.0'));
    run(1.1);
    check('t>3.0: countdown hidden, PLAYING', !vis(cd) && cd.textContent === '' && state === 'PLAYING', snap('3.1'));
    run(1.0);
    check('PLAYING advances simTime ~1.0', Math.abs(simTime - 1.0) < 0.12, snap('after 1s play'));
    check('scrubber tracks simTime', Math.abs(parseFloat(sc.value) - simTime) < 0.0006, sc.value);
    // speed pill
    pills[3].click();
    check('speed 2.0 active', pills[3].classList.contains('is-active') && pills[3].getAttribute('aria-checked') === 'true' && pills.filter(function (p) { return p !== pills[3] && p.getAttribute('aria-checked') === 'false' && !p.classList.contains('is-active'); }).length === 3);
    var t0 = simTime; run(1.0);
    check('2x speed doubles rate', Math.abs((simTime - t0) - 2.0) < 0.15, (simTime - t0).toFixed(3));
    pills[1].click();
    t0 = simTime; run(1.0);
    check('0.5x speed halves rate', Math.abs((simTime - t0) - 0.5) < 0.08, (simTime - t0).toFixed(3));
    pills[2].click();
    // pause
    tg.click();
    check('toggle during PLAYING -> PAUSED, play icon', state === 'PAUSED' && vis(ipl) && !vis(ip) && tg.getAttribute('aria-label') === 'Play', snap('paused'));
    t0 = simTime; run(0.5);
    check('PAUSED freezes simTime', simTime === t0);
    tg.click();
    check('toggle during PAUSED -> PLAYING, pause icon', state === 'PLAYING' && vis(ip) && !vis(ipl) && tg.getAttribute('aria-label') === 'Pause', snap('resumed'));
    // scrub
    sc.value = '4.5'; sc.dispatchEvent(new Event('input', { bubbles: true }));
    check('scrub -> PAUSED @4.5', state === 'PAUSED' && Math.abs(simTime - 4.5) < 1e-9, snap('scrub'));
    run(0.3);
    check('scrub stays paused', state === 'PAUSED' && Math.abs(simTime - 4.5) < 1e-9);
    // speed persists across refire
    pills[3].click();
    rf.click();
    check('refire: REFIRE_HOLD, simTime 0, scrub "0", countdown hidden', state === 'REFIRE_HOLD' && simTime === 0 && sc.value === '0' && !vis(cd) && cd.textContent === '' && vis(ip) && tg.getAttribute('aria-label') === 'Pause', snap('refire'));
    run(0.9);
    check('REFIRE_HOLD @0.9s still hold & countdown hidden', state === 'REFIRE_HOLD' && !vis(cd) && simTime === 0, snap('hold0.9'));
    run(0.2);
    check('REFIRE_HOLD -> PLAYING after 1.0s', state === 'PLAYING', snap('hold1.1'));
    check('speed persisted (2.0)', pills[3].classList.contains('is-active') && playbackSpeed === 2, 'speed=' + playbackSpeed);
    // toggle during REFIRE_HOLD
    rf.click(); run(0.3);
    tg.click();
    check('toggle during REFIRE_HOLD -> PAUSED @0', state === 'PAUSED' && simTime === 0 && !vis(cd), snap('hold-cancel'));
    tg.click(); run(0.3);
    check('PAUSED @0 -> PLAYING', state === 'PLAYING' && simTime > 0, snap('replay'));
    // run to the end at 2x
    run(5.0);
    check('ENDED at DURATION', state === 'ENDED' && simTime === 8 && sc.value === '8.000' || (state === 'ENDED' && simTime === 8 && parseFloat(sc.value) === 8), snap('end') + ' scrubvalue=' + sc.value);
    check('ENDED icons: play shown, label Play', vis(ipl) && !vis(ip) && tg.getAttribute('aria-label') === 'Play', snap('end'));
    tg.click();
    check('toggle in ENDED -> PLAYING from 0, countdown hidden', state === 'PLAYING' && simTime === 0 && !vis(cd) && vis(ip), snap('restart'));
    run(0.2);
    // countdown cancel
    rf.click(); run(0.2);
    // simulate a fresh countdown cancel: no direct way after load, so test scrub-cancel on REFIRE_HOLD
    sc.value = '2.0'; sc.dispatchEvent(new Event('input', { bubbles: true }));
    check('scrub during REFIRE_HOLD cancels hold', state === 'PAUSED' && Math.abs(simTime - 2) < 1e-9 && !vis(cd), snap('scrub-hold'));
    // large dt clamp
    tg.click(); // PLAYING
    var tb = simTime; step(5000);
    check('dt clamped to 0.1 s', Math.abs(simTime - (tb + 0.1 * playbackSpeed)) < 1e-6 || simTime - tb <= 0.2 + 1e-6, 'advanced=' + (simTime - tb).toFixed(4) + ' speed=' + playbackSpeed);
    __L('--- logic test done: ' + fails + ' failures ---');
  } catch (e) { __L('[harness error] ' + e.message + ' ' + (e.stack || '').split('\n').slice(0, 4).join(' | ')); }
  var pre = document.createElement('pre');
  pre.style.cssText = 'position:fixed;left:0;top:0;z-index:2000;background:#000;color:#0f0;font:12px monospace;margin:0;padding:8px;width:100%;height:100%;overflow:hidden';
  pre.textContent = results.join('\n');
  document.body.appendChild(pre);
})();
</script>
'''

RAWLOG = r'''<script>
(function () {
  try {
    applySize(window.innerWidth, window.innerHeight);
    renderAt(0);
    __L('rawlog: gfxOK=' + gfxOK);
  } catch (e) { __L('[harness error] ' + e.message); }
})();
</script>
'''

