/* ---------------- Mach cone (faint shock V behind the supersonic nose) ---------------- */
const CONE_VERT = `
varying vec2 vUv;
void main() {
  vUv = uv;
  gl_Position = projectionMatrix * modelViewMatrix * vec4( position, 1.0 );
}
`;
const CONE_FRAG = `
uniform float uInt;
varying vec2 vUv;
void main() {
  float x = vUv.x * 2.6;                    /* distance behind the nose */
  float y = ( vUv.y - 0.5 ) * 1.7;
  float tanMu = 0.38;
  float d = abs( abs( y ) - x * tanMu );
  float fade = ( 1.0 - smoothstep( 0.0, 2.6, x ) ) * smoothstep( 0.0, 0.06, x );
  float line = exp( - pow( d / 0.011, 2.0 ) ) * fade;
  float halo = exp( - pow( d / 0.055, 2.0 ) ) * fade * 0.20;
  float inside = step( abs( y ), x * tanMu ) * exp( - x * 1.4 ) * 0.045;
  float bow = exp( - pow( ( x - 0.02 - 1.9 * y * y ) / 0.012, 2.0 ) ) * step( x, 0.16 );
  vec3 c = vec3( 0.58, 0.80, 1.0 ) * ( line * 0.85 + halo + inside + bow * 0.9 ) * uInt;
  gl_FragColor = vec4( c, clamp( max( c.r, max( c.g, c.b ) ), 0.0, 1.0 ) );
}
`;

