/* THREE.InstancedMesh whose instance matrices stay identity: every particle's motion is analytic in the vertex shader */
function makeInstanced(geo, mat, count) {
  const mesh = new THREE.InstancedMesh(geo, mat, count);
  const I = new THREE.Matrix4();
