216	<script>
217	'use strict';
218	/* =====================================================================
219	   PRINCE RUPERT'S DROP — BULLET IMPACT vs. TAIL SNIP
220	   Everything visible is a pure function of simTime (renderAt), driven by
221	   analytic particle motion in the vertex shaders and a seed-42 PRNG that
222	   is only consumed while the procedural data is generated at start-up.
223	   ===================================================================== */
224	
225	/* ------------------------------------------------------------------ *
226	 * 1. Constants, timeline anchors, tiny helpers
227	 * ------------------------------------------------------------------ */
228	const DURATION = 8;
229	const FOV_DEG = 35;           // 85 mm-equivalent narrow lens
230	const SEED = 42;
231	
232	const T_IMPACT  = 1.2;        // lead nose touches the bulb
233	const T_PULSE_A = 2.6;        // photoelastic pulse window
234	const T_PULSE_B = 3.8;
235	const T_TOUCH   = 3.8;        // jaws reach the tail
236	const T_SNIP    = 4.06;       // tail tip severed
237	const T_FRONT_A = 4.4;        // fracture front leaves the tail  (s = 1)
238	const T_FRONT_B = 5.8;        // ... and arrives at the bulb      (s = 0)
239	const T_BURST   = 5.8;        // catastrophic radial disintegration
240	const BAND_W    = 0.08;       // opaque white crack band width (in s)
241	
242	const BULB_R = 0.62;          // bulb radius (world units)
243	const V_BULLET = 7.5;         // bullet speed (units / s) before contact
244	
245	function mulberry32(a) {
246	  return function () {
247	    a |= 0; a = (a + 0x6D2B79F5) | 0;
248	    let t = Math.imul(a ^ (a >>> 15), 1 | a);
249	    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
250	    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
251	  };
252	}
253	let rng = mulberry32(SEED);
254	function resetRng() { rng = mulberry32(SEED); }
255	const rand = () => rng();
256	const randRange = (a, b) => a + (b - a) * rng();
257	
258	const clamp = (x, a, b) => Math.min(b, Math.max(a, x));
259	const lerp = (a, b, t) => a + (b - a) * t;
260	const sstep = (a, b, x) => { const t = clamp((x - a) / (b - a), 0, 1); return t * t * (3 - 2 * t); };
261	const deg = (d) => d * Math.PI / 180;
262	/* r128 materials are linear: decode the sRGB hex so "dark grey" really is dark */
263	const srgb = (hex) => new THREE.Color(hex).convertSRGBToLinear();
264	
265	/* ------------------------------------------------------------------ *
266	 * 2. DOM handles and playback state
267	 * ------------------------------------------------------------------ */
268	const elCountdown = document.getElementById('countdown');
269	const elToggle = document.getElementById('btn-toggle');
270	const elRefire = document.getElementById('btn-refire');
271	const elIconPause = document.getElementById('icon-pause');
272	const elIconPlay = document.getElementById('icon-play');
273	const elScrubber = document.getElementById('scrubber');
274	const elPills = Array.prototype.slice.call(document.querySelectorAll('.speed-pill'));
275	
276	let state = 'COUNTDOWN';      // COUNTDOWN | PLAYING | PAUSED | REFIRE_HOLD | ENDED
277	let simTime = 0;
278	let playbackSpeed = 1;
279	let countdownElapsed = 0;
280	let holdElapsed = 0;
281	let lastTs = null;
282	let needsRender = true;
283	
284	/* three.js objects (assigned in initGraphics) */
285	let renderer = null, scene = null, camera = null, envTex = null, SP = null;
286	let gfxOK = false;
287	const G = {};                 // scene references used by renderAt
288	
289	/* ------------------------------------------------------------------ *
290	 * 3. GLSL building blocks
291	 * ------------------------------------------------------------------ */
292	const GLSL_NOISE = `
293	float h11( float p ) { p = fract( p * .1031 ); p *= p + 33.33; p *= p + p; return fract( p ); }
294	float h21( vec2 p ) { vec3 p3 = fract( vec3( p.xyx ) * .1031 ); p3 += dot( p3, p3.yzx + 33.33 ); return fract( ( p3.x + p3.y ) * p3.z ); }
295	vec2 h22( vec2 p ) { vec3 p3 = fract( vec3( p.xyx ) * vec3( .1031, .1030, .0973 ) ); p3 += dot( p3, p3.yzx + 33.33 ); return fract( ( p3.xx + p3.yz ) * p3.zy ); }
296	float h31( vec3 p ) { p = fract( p * .1031 ); p += dot( p, p.zyx + 31.32 ); return fract( ( p.x + p.y ) * p.z ); }
297	float vn2( vec2 p ) {
298	  vec2 i = floor( p ), f = fract( p ); f = f * f * ( 3. - 2. * f );
299	  return mix( mix( h21( i ), h21( i + vec2( 1., 0. ) ), f.x ), mix( h21( i + vec2( 0., 1. ) ), h21( i + vec2( 1., 1. ) ), f.x ), f.y );
300	}
301	float vn3( vec3 p ) {
302	  vec3 i = floor( p ), f = fract( p ); f = f * f * ( 3. - 2. * f );
303	  return mix( mix( mix( h31( i ), h31( i + vec3( 1., 0., 0. ) ), f.x ), mix( h31( i + vec3( 0., 1., 0. ) ), h31( i + vec3( 1., 1., 0. ) ), f.x ), f.y ),
304	              mix( mix( h31( i + vec3( 0., 0., 1. ) ), h31( i + vec3( 1., 0., 1. ) ), f.x ), mix( h31( i + vec3( 0., 1., 1. ) ), h31( i + vec3( 1., 1., 1. ) ), f.x ), f.y ), f.z );
305	}
306	vec3 rotAxis( vec3 v, vec3 k, float a ) { float c = cos( a ), s = sin( a ); return v * c + cross( k, v ) * s + k * dot( k, v ) * ( 1. - c ); }
307	`;
308	
309	/* analytic particle motion shared by needles and dust:
310	   slow swelling while the front passes, then a drag-limited radial burst
311	   at T_BURST, with a drag-limited downward drift (gravity). */
312	const GLSL_MOTION = `
313	vec3 particleOffset( float tAct, vec3 dir, float vSlow, float vBurst, float vTerm, float tBurst, float t ) {
314	  float age = max( t - tAct, 0.0 );
315	  float a1 = max( min( t, tBurst ) - tAct, 0.0 );
316	  float a2 = max( t - max( tBurst, tAct ), 0.0 );
317	  float disp = vSlow * a1 + vBurst * ( 1.0 - exp( -1.9 * a2 ) ) / 1.9;
318	  vec3 off = dir * disp;
319	  off.y -= vTerm * ( age - ( 1.0 - exp( -1.1 * age ) ) / 1.1 );
320	  return off;
321	}
322	`;
323	
324	function patch(src, token, repl, label) {
325	  if (src.indexOf(token) < 0) { console.error('[patch] token missing: ' + token + ' (' + label + ')'); return src; }
326	  return src.replace(token, function () { return repl; });
327	}
328	
329	/* ---------------- glass: vertex ---------------- */
330	const GLASS_VERT_PARS = `
331	attribute float aS;
332	attribute float aPhi;
333	attribute float aRad;
334	uniform float uPush;
335	uniform float uClampS;
336	varying float vS;
337	varying float vPhi;
338	varying float vRad;
339	varying vec3 vWPos;
340	`;
341	const GLASS_VERT_BEGIN = `
342	vec3 transformed = vec3( position );
343	{
344	  float wb = 1.0 - smoothstep( 0.0, uClampS, aS );
345	  wb *= wb;

690	}
691	`;
692	const CONE_FRAG = `
693	uniform float uInt;
694	varying vec2 vUv;
695	void main() {
696	  float x = vUv.x * 2.6;                    /* distance behind the nose */
697	  float y = ( vUv.y - 0.5 ) * 1.7;
698	  float tanMu = 0.38;
699	  float d = abs( abs( y ) - x * tanMu );
700	  float fade = ( 1.0 - smoothstep( 0.0, 2.6, x ) ) * smoothstep( 0.0, 0.06, x );
701	  float line = exp( - pow( d / 0.011, 2.0 ) ) * fade;
702	  float halo = exp( - pow( d / 0.055, 2.0 ) ) * fade * 0.20;
703	  float inside = step( abs( y ), x * tanMu ) * exp( - x * 1.4 ) * 0.045;
704	  float bow = exp( - pow( ( x - 0.02 - 1.9 * y * y ) / 0.012, 2.0 ) ) * step( x, 0.16 );
705	  vec3 c = vec3( 0.58, 0.80, 1.0 ) * ( line * 0.85 + halo + inside + bow * 0.9 ) * uInt;
706	  gl_FragColor = vec4( c, clamp( max( c.r, max( c.g, c.b ) ), 0.0, 1.0 ) );
707	}
708	`;
709	
710	/* ------------------------------------------------------------------ *
711	 * 4. Scene construction
712	 * ------------------------------------------------------------------ */
713	
714	/* 4a. Procedural studio light-box -> PMREM cube-UV environment */
715	function buildEnvTexture() {
716	  const envScene = new THREE.Scene();
717	  const room = new THREE.Mesh(
718	    new THREE.BoxGeometry(60, 40, 60),
719	    new THREE.MeshBasicMaterial({ color: new THREE.Color(0.014, 0.016, 0.022), side: THREE.BackSide })
720	  );
721	  envScene.add(room);
722	  function panel(w, h, x, y, z, col, k) {
723	    const m = new THREE.Mesh(
724	      new THREE.PlaneGeometry(w, h),
725	      new THREE.MeshBasicMaterial({ color: new THREE.Color(col[0] * k, col[1] * k, col[2] * k), side: THREE.DoubleSide })
726	    );
727	    m.position.set(x, y, z);
728	    m.lookAt(0, 0, 0);
729	    envScene.add(m);
730	  }
731	  panel(14, 8, -9, 11, 12, [0.92, 0.97, 1.0], 9.0);      // key softbox (cool white)
732	  panel(18, 4, 0, 16, 2, [1.0, 1.0, 1.0], 5.0);          // overhead strip
733	  panel(4, 18, 15, 2, 9, [1.0, 0.96, 0.92], 3.2);        // fill strip
734	  panel(3, 14, -16, 0, 6, [0.90, 0.95, 1.0], 2.0);       // left card
735	  panel(3.5, 18, -14, 1, -12, [0.25, 0.90, 1.0], 8.0);   // cyan rim strip
736	  panel(3.5, 18, 14, 1, -12, [1.0, 0.25, 0.85], 7.0);    // magenta rim strip
737	  panel(20, 10, 0, -14, 6, [0.80, 0.90, 1.0], 1.2);      // floor bounce
738	  panel(30, 16, 0, 2, -20, [0.35, 0.42, 0.55], 0.7);     // back wall
739	  const pm = new THREE.PMREMGenerator(renderer);
740	  const rt = pm.fromScene(envScene, 0.012);
741	  pm.dispose();
742	  return rt.texture;
743	}
744	
745	/* 4b. Spine: bulb (s = 0) -> neck -> helical tail tip (s = 1), arc-length parameterised */
746	const R_J_ANGLE = deg(130);
747	const A_JUNC = BULB_R * (1 - Math.cos(R_J_ANGLE));
748	const R_JUNC = BULB_R * Math.sin(R_J_ANGLE);
749	const R_TAIL = 0.026;
750	const LAMBDA = (R_JUNC - R_TAIL) / Math.tan(deg(40));
751	const CAP_LEN = 0.045;
752	
753	function radiusAt(a, L) {
754	  if (a <= 0) return 0;
755	  let r;
756	  if (a < A_JUNC) r = Math.sqrt(Math.max(0, BULB_R * BULB_R - (a - BULB_R) * (a - BULB_R)));
757	  else r = R_TAIL + (R_JUNC - R_TAIL) * Math.exp(-(a - A_JUNC) / LAMBDA);
758	  const aCap = L - CAP_LEN;
759	  if (a > aCap) { const q = (a - aCap) / CAP_LEN; r *= Math.sqrt(Math.max(0, 1 - q * q)); }
760	  return r;
761	}
762	
763	function buildSpine() {
764	  const V3 = THREE.Vector3;
765	  const ctrl = [
766	    new V3(0.10, -2.20, 0), new V3(0.10, -1.58, 0), new V3(0.15, -0.88, 0), new V3(0.36, -0.12, 0),
767	    new V3(0.30, 0.70, 0), new V3(-0.08, 1.32, 0), new V3(-0.55, 1.74, 0), new V3(-1.12, 1.98, 0)
768	  ];
769	  const base = new THREE.CatmullRomCurve3(ctrl, false, 'centripetal');
770	  const M = 2400;
771	  const px = new Float64Array(M + 1), py = new Float64Array(M + 1), pz = new Float64Array(M + 1);
772	  const U0 = 0.50, U1 = 0.905, TURNS = 2.5, HAMP = 0.15;
773	  for (let i = 0; i <= M; i++) {
774	    const u = i / M;
775	    const p = base.getPoint(u);
776	    const tg = base.getTangent(u);
777	    let nx = -tg.y, ny = tg.x;
778	    const nl = Math.hypot(nx, ny) || 1; nx /= nl; ny /= nl;
779	    const env = sstep(U0, U0 + 0.10, u) * (1 - sstep(U1 - 0.09, U1, u));
780	    const ph = Math.PI * 2 * TURNS * (u - U0) / (U1 - U0);
781	    const off = HAMP * env;
782	    px[i] = p.x + nx * off * Math.cos(ph);
783	    py[i] = p.y + ny * off * Math.cos(ph);
784	    pz[i] = off * Math.sin(ph);
785	  }
786	  const cum = new Float64Array(M + 1);
787	  for (let i = 1; i <= M; i++) cum[i] = cum[i - 1] + Math.hypot(px[i] - px[i - 1], py[i] - py[i - 1], pz[i] - pz[i - 1]);
788	  const L = cum[M];
789	
790	  const S = { L: L };
791	  S.posAtA = function (a, out) {
792	    a = clamp(a, 0, L);
793	    let lo = 0, hi = M;
794	    while (hi - lo > 1) { const mid = (lo + hi) >> 1; if (cum[mid] <= a) lo = mid; else hi = mid; }
795	    const seg = cum[hi] - cum[lo];
796	    const f = seg > 0 ? (a - cum[lo]) / seg : 0;
797	    return out.set(lerp(px[lo], px[hi], f), lerp(py[lo], py[hi], f), lerp(pz[lo], pz[hi], f));
798	  };
799	  S.tanAtA = function (a, out) {
800	    const e = 0.004;
801	    const p0 = S.posAtA(Math.max(0, a - e), new V3()), p1 = S.posAtA(Math.min(L, a + e), new V3());
802	    return out.copy(p1).sub(p0).normalize();
803	  };
804	
805	  /* ring list: dome rings (uniform polar angle), neck rings (uniform arc length), tip-cap rings */
806	  const ringA = [], domeK = 34;
807	  for (let k = 0; k <= domeK; k++) ringA.push(BULB_R * (1 - Math.cos(R_J_ANGLE * k / domeK)));
808	  const aEnd = L - CAP_LEN, nNeck = 300;
809	  for (let k = 1; k <= nNeck; k++) ringA.push(A_JUNC + (aEnd - A_JUNC) * k / nNeck);
810	  const nCap = 8;
811	  for (let k = 1; k <= nCap; k++) ringA.push(aEnd + CAP_LEN * Math.sin(Math.PI / 2 * k / nCap));
812	  const NR = ringA.length;
813	  S.ringA = ringA; S.nDome = domeK + 1;
814	  S.ringS = ringA.map(a => a / L);
815	  S.ringR = ringA.map(a => radiusAt(a, L));
816	  S.ringC = []; S.ringT = []; S.ringN = []; S.ringB = [];
817	  for (let i = 0; i < NR; i++) {
818	    S.ringC.push(S.posAtA(ringA[i], new V3()));
819	    S.ringT.push(S.tanAtA(ringA[i], new V3()));
820	  }
821	  /* rotation-minimising frames (parallel transport) */
822	  let Nprev = new V3(1, 0, 0);
823	  for (let i = 0; i < NR; i++) {
824	    const T = S.ringT[i];
825	    const N = Nprev.clone().addScaledVector(T, -Nprev.dot(T)).normalize();
826	    S.ringN.push(N); S.ringB.push(new V3().crossVectors(T, N).normalize());
827	    Nprev = N;
828	  }
829	
830	  S.frameAt = function (s, out) {
831	    s = clamp(s, 0, 1);
832	    const SS = S.ringS; let lo = 0, hi = SS.length - 1;
833	    while (hi - lo > 1) { const mid = (lo + hi) >> 1; if (SS[mid] <= s) lo = mid; else hi = mid; }
834	    const f = (s - SS[lo]) / Math.max(1e-9, SS[hi] - SS[lo]);
835	    out.C.copy(S.ringC[lo]).lerp(S.ringC[hi], f);
836	    out.T.copy(S.ringT[lo]).lerp(S.ringT[hi], f).normalize();
837	    out.N.copy(S.ringN[lo]).lerp(S.ringN[hi], f);
838	    out.N.addScaledVector(out.T, -out.N.dot(out.T)).normalize();
