850	      cdf[i] = acc;
851	    }
852	    for (let i = 0; i < NR; i++) cdf[i] /= acc;
853	    return function (u) {
854	      let lo = 0, hi = NR - 1;
855	      while (hi - lo > 1) { const mid = (lo + hi) >> 1; if (cdf[mid] <= u) lo = mid; else hi = mid; }
