/* 4b. Spine: bulb (s = 0) -> neck -> helical tail tip (s = 1), arc-length parameterised */
const R_J_ANGLE = deg(130);
const A_JUNC = BULB_R * (1 - Math.cos(R_J_ANGLE));
const R_JUNC = BULB_R * Math.sin(R_J_ANGLE);
const R_TAIL = 0.026;
const LAMBDA = (R_JUNC - R_TAIL) / Math.tan(deg(40));
const CAP_LEN = 0.045;

function radiusAt(a, L) {
  if (a <= 0) return 0;
  let r;
  if (a < A_JUNC) r = Math.sqrt(Math.max(0, BULB_R * BULB_R - (a - BULB_R) * (a - BULB_R)));
  else r = R_TAIL + (R_JUNC - R_TAIL) * Math.exp(-(a - A_JUNC) / LAMBDA);
  const aCap = L - CAP_LEN;
  if (a > aCap) { const q = (a - aCap) / CAP_LEN; r *= Math.sqrt(Math.max(0, 1 - q * q)); }
  return r;
}

function buildSpine() {
  const V3 = THREE.Vector3;
  const ctrl = [
    new V3(0.10, -2.20, 0), new V3(0.10, -1.58, 0), new V3(0.15, -0.88, 0), new V3(0.36, -0.12, 0),
    new V3(0.30, 0.70, 0), new V3(-0.08, 1.32, 0), new V3(-0.55, 1.74, 0), new V3(-1.12, 1.98, 0)
  ];
