  const M = 2400;
  const px = new Float64Array(M + 1), py = new Float64Array(M + 1), pz = new Float64Array(M + 1);
  const U0 = 0.50, U1 = 0.905, TURNS = 2.5, HAMP = 0.15;
  for (let i = 0; i <= M; i++) {
    const u = i / M;
    const p = base.getPoint(u);
    const tg = base.getTangent(u);
    let nx = -tg.y, ny = tg.x;
    const nl = Math.hypot(nx, ny) || 1; nx /= nl; ny /= nl;
    const env = sstep(U0, U0 + 0.10, u) * (1 - sstep(U1 - 0.09, U1, u));
    const ph = Math.PI * 2 * TURNS * (u - U0) / (U1 - U0);
    const off = HAMP * env;
    px[i] = p.x + nx * off * Math.cos(ph);
    py[i] = p.y + ny * off * Math.cos(ph);
    pz[i] = off * Math.sin(ph);
  }
  const cum = new Float64Array(M + 1);
  for (let i = 1; i <= M; i++) cum[i] = cum[i - 1] + Math.hypot(px[i] - px[i - 1], py[i] - py[i - 1], pz[i] - pz[i - 1]);
  const L = cum[M];

  const S = { L: L };
  S.posAtA = function (a, out) {
    a = clamp(a, 0, L);
    let lo = 0, hi = M;
    while (hi - lo > 1) { const mid = (lo + hi) >> 1; if (cum[mid] <= a) lo = mid; else hi = mid; }
    const seg = cum[hi] - cum[lo];
    const f = seg > 0 ? (a - cum[lo]) / seg : 0;
    return out.set(lerp(px[lo], px[hi], f), lerp(py[lo], py[hi], f), lerp(pz[lo], pz[hi], f));
  };
