  S.frameAt = function (s, out) {
    s = clamp(s, 0, 1);
    const SS = S.ringS; let lo = 0, hi = SS.length - 1;
    while (hi - lo > 1) { const mid = (lo + hi) >> 1; if (SS[mid] <= s) lo = mid; else hi = mid; }
    const f = (s - SS[lo]) / Math.max(1e-9, SS[hi] - SS[lo]);
