  m.onBeforeCompile = function (shader) {
    Object.assign(shader.uniforms, G.glassU);
    let v = shader.vertexShader, f = shader.fragmentShader;
    v = patch(v, '#include <common>', '#include <common>\n' + GLASS_VERT_PARS, 'glass vert pars');
    v = patch(v, '#include <begin_vertex>', GLASS_VERT_BEGIN, 'glass vert begin');
    v = patch(v, '#include <project_vertex>', GLASS_VERT_PROJ, 'glass vert proj');
    f = patch(f, '#include <common>', '#include <common>\n' + GLASS_FRAG_PARS, 'glass frag pars');
    f = patch(f, '#include <clipping_planes_fragment>', '#include <clipping_planes_fragment>\n' + GLASS_FRAG_PROLOGUE, 'glass frag prologue');
    f = patch(f, '#include <tonemapping_fragment>', glassFragTail(back) + '\n#include <tonemapping_fragment>', 'glass frag tail');
    f = patch(f, '#include <dithering_fragment>', GLASS_FRAG_ALPHA, 'glass frag alpha');
    shader.vertexShader = v; shader.fragmentShader = f;
  };
  m.customProgramCacheKey = function () { return back ? 'prd-glass-back' : 'prd-glass-front'; };
  return m;
}

function buildGlass() {
  const NS = 48, NR = SP.ringA.length, nV = NR * (NS + 1);
  const pos = new Float32Array(nV * 3), nor = new Float32Array(nV * 3);
  const aS = new Float32Array(nV), aPhi = new Float32Array(nV), aRad = new Float32Array(nV);
  const index = [];
  for (let i = 0; i < NR; i++) {
    const C = SP.ringC[i], T = SP.ringT[i], N = SP.ringN[i], B = SP.ringB[i], r = SP.ringR[i];
    const i0 = Math.max(0, i - 1), i1 = Math.min(NR - 1, i + 1);
    const rp = (SP.ringR[i1] - SP.ringR[i0]) / Math.max(1e-6, SP.ringA[i1] - SP.ringA[i0]);
    const isDome = i < SP.nDome;
    const phi = isDome ? R_J_ANGLE * i / (SP.nDome - 1) : 0;
    for (let j = 0; j <= NS; j++) {
      const th = j / NS * Math.PI * 2, c = Math.cos(th), s = Math.sin(th);
      const rx = N.x * c + B.x * s, ry = N.y * c + B.y * s, rz = N.z * c + B.z * s;
      const k = (i * (NS + 1) + j);
      pos[k * 3] = C.x + rx * r; pos[k * 3 + 1] = C.y + ry * r; pos[k * 3 + 2] = C.z + rz * r;
      let nx, ny, nz;
      if (i === 0) { nx = -T.x; ny = -T.y; nz = -T.z; }
      else if (i === NR - 1) { nx = T.x; ny = T.y; nz = T.z; }
      else if (isDome) {
        const sp = Math.sin(phi), cp = Math.cos(phi);
        nx = sp * rx - cp * T.x; ny = sp * ry - cp * T.y; nz = sp * rz - cp * T.z;
      } else {
        const inv = 1 / Math.sqrt(1 + rp * rp);
        nx = (rx - T.x * rp) * inv; ny = (ry - T.y * rp) * inv; nz = (rz - T.z * rp) * inv;
      }
      nor[k * 3] = nx; nor[k * 3 + 1] = ny; nor[k * 3 + 2] = nz;
      aS[k] = SP.ringS[i]; aPhi[k] = th; aRad[k] = r;
    }
  }
  for (let i = 0; i < NR - 1; i++) {
    for (let j = 0; j < NS; j++) {
      const a = i * (NS + 1) + j, b = (i + 1) * (NS + 1) + j, c = a + 1, d = b + 1;
      index.push(a, c, b, b, c, d);
    }
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  geo.setAttribute('normal', new THREE.BufferAttribute(nor, 3));
  geo.setAttribute('aS', new THREE.BufferAttribute(aS, 1));
  geo.setAttribute('aPhi', new THREE.BufferAttribute(aPhi, 1));
  geo.setAttribute('aRad', new THREE.BufferAttribute(aRad, 1));
  geo.setIndex(index);

  G.glassU = {
    uTime: { value: 0 }, uFront: { value: 3 }, uCutS: { value: SP.S_CUT }, uSnip: { value: 0 }, uNuc: { value: 0 },
    uStress: { value: 0.5 }, uPulse: { value: 0 }, uRing: { value: 0 }, uImpactT: { value: -1 },
    uImpactPos: { value: new THREE.Vector3(SP.bulbCenter.x + BULB_R, SP.bulbCenter.y, 0) },
    uTransGain: { value: 0.85 }, uPush: { value: 0 }, uClampS: { value: SP.S_CLAMP }
  };
  G.glassBack = new THREE.Mesh(geo, makeGlassMaterial(true));
  G.glassFront = new THREE.Mesh(geo, makeGlassMaterial(false));
  G.glassBack.renderOrder = 1; G.glassFront.renderOrder = 2;
  G.glassBack.frustumCulled = false; G.glassFront.frustumCulled = false;
  scene.add(G.glassBack); scene.add(G.glassFront);
}

/* brushed tool-steel streak map (detached 2D canvas, never added to the DOM) */
function makeBrushedTexture() {
  const c = document.createElement('canvas'); c.width = 256; c.height = 256;
  const g = c.getContext('2d');
  g.fillStyle = '#9a9a9a'; g.fillRect(0, 0, 256, 256);
  for (let i = 0; i < 1500; i++) {
    const y = rand() * 256, len = 30 + rand() * 220, x = rand() * 256;
    const v = 70 + Math.floor(rand() * 150);
    g.fillStyle = 'rgba(' + v + ',' + v + ',' + v + ',' + (0.10 + 0.28 * rand()).toFixed(3) + ')';
    g.fillRect(x, y, len, 1);
    if (x + len > 256) g.fillRect(x - 256, y, len, 1);
  }
  const t = new THREE.CanvasTexture(c);
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  return t;
}

function buildLights() {
  function add(l, x, y, z) { l.position.set(x, y, z); scene.add(l); return l; }
  G.key = add(new THREE.DirectionalLight(0xe4f0ff, 1.7), -5, 7, 9);
  G.fill = add(new THREE.DirectionalLight(0xfff4ec, 0.35), 8, 1, 7);
  G.rimC = add(new THREE.DirectionalLight(0x35e6ff, 0.9), -8, 3, -7);
  G.rimM = add(new THREE.DirectionalLight(0xff3fd0, 0.8), 8, 2, -7);
  G.frontLight = new THREE.PointLight(0xa4d2ff, 0, 9, 2);
  scene.add(G.frontLight);
}

/* 4d. Dark anodised clamp + rod ------------------------------------ */
function buildClamp() {
  const V3 = THREE.Vector3;
  const fr = { C: new V3(), T: new V3(), N: new V3(), B: new V3(), r: 0 };
  SP.frameAt(SP.S_CLAMP, fr);
  const mat = new THREE.MeshStandardMaterial({ color: srgb(0x23262d), metalness: 0.85, roughness: 0.40, envMap: envTex, envMapIntensity: 0.5 });
  const rodMat = new THREE.MeshStandardMaterial({ color: srgb(0x16181d), metalness: 0.8, roughness: 0.6, envMap: envTex, envMapIntensity: 0.22 });
  const grp = new THREE.Group();
  grp.position.copy(fr.C);
  grp.quaternion.setFromUnitVectors(new V3(0, 1, 0), fr.T);
  const ri = fr.r + 0.016, ro = fr.r + 0.115, hw = 0.10;
  const prof = [
    new THREE.Vector2(ri, -hw), new THREE.Vector2(ro - 0.014, -hw), new THREE.Vector2(ro, -hw + 0.014),
    new THREE.Vector2(ro, hw - 0.014), new THREE.Vector2(ro - 0.014, hw), new THREE.Vector2(ri, hw), new THREE.Vector2(ri, -hw)
  ];
  grp.add(new THREE.Mesh(new THREE.LatheGeometry(prof, 48), mat));
  /* clamp block, screw, and rod (in the ring's local frame: Y = spine tangent) */
  const back = new V3(-0.55, 0, -0.83).normalize();                 // direction away from the camera, toward the stand
  const blockPos = back.clone().multiplyScalar(ro + 0.05);
  const block = new THREE.Mesh(new THREE.BoxGeometry(0.17, 0.26, 0.17), mat);
  block.position.copy(blockPos);
  block.quaternion.setFromUnitVectors(new V3(0, 0, 1), back);
  grp.add(block);
  const screw = new THREE.Mesh(new THREE.CylinderGeometry(0.045, 0.045, 0.2, 18), mat);
  screw.position.copy(back.clone().multiplyScalar(ro + 0.19)).add(new V3(0, 0.0, 0));
  screw.quaternion.setFromUnitVectors(new V3(0, 1, 0), back);
  grp.add(screw);
  scene.add(grp);
  G.clamp = grp;
  /* the stand rod runs away behind the drop toward the lower left */
  const rodDirW = new V3(-0.50, -0.30, -0.81).normalize();
  const blockWorld = blockPos.clone().applyQuaternion(grp.quaternion).add(grp.position);
  const rod = new THREE.Mesh(new THREE.CylinderGeometry(0.03, 0.03, 14, 14), rodMat);
  rod.position.copy(blockWorld).addScaledVector(rodDirW, 7.0);
  rod.quaternion.setFromUnitVectors(new V3(0, 1, 0), rodDirW);
  scene.add(rod);
}

/* 4e. Steel nippers ------------------------------------------------- */
const JAW_L = 0.96;
const BETA_T = deg(7.6);      // arm angle at which the jaw faces just touch the tail
const BETA_OPEN = deg(17);
const GAP_HALF = 0.034;

function buildNippers() {
  const V3 = THREE.Vector3;
  const steel = new THREE.MeshStandardMaterial({
    color: srgb(0x7b828d), metalness: 1.0, roughness: 0.60, roughnessMap: makeBrushedTexture(),
    envMap: envTex, envMapIntensity: 0.5
  });
  const rubber = new THREE.MeshStandardMaterial({ color: srgb(0x0f1115), metalness: 0.0, roughness: 0.5, envMap: envTex, envMapIntensity: 0.3 });
  const pinMat = new THREE.MeshStandardMaterial({ color: srgb(0x8a909a), metalness: 1.0, roughness: 0.3, envMap: envTex, envMapIntensity: 0.7 });

  const rot = (x, y, a) => [x * Math.cos(a) - y * Math.sin(a), x * Math.sin(a) + y * Math.cos(a)];
  const toArm = (x, y) => rot(x, y, -BETA_T);
  const F0 = toArm(0.60, GAP_HALF), F1 = toArm(0.965, GAP_HALF), TIP = toArm(0.985, GAP_HALF + 0.045);
  const O1 = toArm(0.90, GAP_HALF + 0.15), O0 = toArm(0.52, GAP_HALF + 0.17);
  const armPts = [
    [-1.15, -0.085], [-0.30, -0.100], [0.0, -0.115], [0.30, -0.105], F0, F1, TIP, O1, O0,
    [0.30, 0.105], [0.0, 0.115], [-0.30, 0.100], [-1.15, 0.085]
  ];
  const shape = new THREE.Shape();
  armPts.forEach((p, i) => { if (i === 0) shape.moveTo(p[0], p[1]); else shape.lineTo(p[0], p[1]); });
  shape.closePath();
  const ext = { depth: 0.13, bevelEnabled: true, bevelThickness: 0.012, bevelSize: 0.010, bevelSegments: 2, curveSegments: 4 };
  function armGeo(dz) { const g = new THREE.ExtrudeGeometry(shape, ext); g.translate(0, 0, -0.065 + dz); return g; }

  /* rubber grip (rounded slab on the handle end) */
  const gs = new THREE.Shape();
  const gx0 = -3.6, gx1 = -1.10, gw = 0.135, gr = 0.09;
  gs.moveTo(gx0 + gr, -gw); gs.lineTo(gx1 - 0.03, -gw + 0.012); gs.lineTo(gx1, -gw + 0.03); gs.lineTo(gx1, gw - 0.03);
  gs.lineTo(gx1 - 0.03, gw - 0.012); gs.lineTo(gx0 + gr, gw);
  gs.quadraticCurveTo(gx0, gw, gx0, gw - gr); gs.lineTo(gx0, -gw + gr); gs.quadraticCurveTo(gx0, -gw, gx0 + gr, -gw);
  const gext = { depth: 0.19, bevelEnabled: true, bevelThickness: 0.02, bevelSize: 0.02, bevelSegments: 3, curveSegments: 8 };
  function gripGeo() { const g = new THREE.ExtrudeGeometry(gs, gext); g.translate(0, 0, -0.095); return g; }

  const armA = new THREE.Group(), armB = new THREE.Group();
  const aMesh = new THREE.Mesh(armGeo(0.004), steel), aGrip = new THREE.Mesh(gripGeo(), rubber);
  const bMesh = new THREE.Mesh(armGeo(-0.004), steel), bGrip = new THREE.Mesh(gripGeo(), rubber);
  armA.add(aMesh, aGrip);
  armB.add(bMesh, bGrip);
  armB.scale.y = -1;                     // mirror image across the tool axis
  const tool = new THREE.Group();
  tool.add(armA, armB);
  const pin = new THREE.Mesh(new THREE.CylinderGeometry(0.058, 0.058, 0.30, 24), pinMat);
  pin.rotation.x = Math.PI / 2;
  tool.add(pin);
  [-1, 1].forEach(sg => {
    const w = new THREE.Mesh(new THREE.CylinderGeometry(0.105, 0.105, 0.022, 28), pinMat);
    w.rotation.x = Math.PI / 2; w.position.z = sg * 0.092; tool.add(w);
    const hd = new THREE.Mesh(new THREE.CylinderGeometry(0.07, 0.07, 0.03, 6), pinMat);
    hd.rotation.x = Math.PI / 2; hd.position.z = sg * 0.118; tool.add(hd);
  });

  const u = SP.tCut.clone().multiplyScalar(-1);             // pivot -> jaw tips
  G.uDir = new V3(u.x, u.y, 0).normalize();
  G.pivot = SP.pCut.clone().addScaledVector(SP.tCut, JAW_L); // the pivot sits beyond the tail tip
  tool.rotation.z = Math.atan2(G.uDir.y, G.uDir.x);
  tool.position.copy(G.pivot);
  scene.add(tool);
  G.tool = tool; G.armA = armA; G.armB = armB;
}

function jawBeta(t) {
  const touch = BETA_T + deg(0.25), closed = BETA_T - deg(1.9);
  if (t < T_PULSE_A) return BETA_OPEN;
  if (t < T_TOUCH) {
    const k = sstep(T_PULSE_A, T_TOUCH, t);
    return lerp(BETA_OPEN, touch, k);
  }
  if (t < T_SNIP) {
    const k = (t - T_TOUCH) / (T_SNIP - T_TOUCH);
    return lerp(touch, BETA_T - deg(0.35), k * k);
  }
  return lerp(BETA_T - deg(0.35), closed, sstep(T_SNIP, T_SNIP + 0.09, t));
}

/* 4f. Lead bullet (copper-jacketed, mushrooms on impact) ------------- */
function buildBullet() {
  const BS = 1.14;                                  // overall bullet scale
  const R0 = 0.17 * BS, LB = 1.0 * BS, AN = 0.58 * BS, A_CAP = 0.60 * BS, CH = 0.06 * BS;
  const NOSE = 40, CYL = 14, CHAM = 4;
  const P0 = [];
  for (let i = 0; i <= NOSE; i++) {
    const a = AN * Math.pow(i / NOSE, 1.25), uu = a / AN;
    P0.push([a, R0 * Math.sin(0.5 * Math.PI * Math.pow(uu, 0.85))]);
  }
  for (let i = 1; i <= CYL; i++) P0.push([AN + (LB - CH - AN) * i / CYL, R0]);
  for (let i = 1; i <= CHAM; i++) { const q = i / CHAM; P0.push([LB - CH + CH * q, R0 * (1 - 0.14 * q)]); }
  P0.push([LB, R0 * 0.55]); P0.push([LB, 0.0]);
  const N = P0.length, iCap = NOSE;

