  const m = new THREE.ShaderMaterial({ uniforms: u, vertexShader: GLOW_VERT, fragmentShader: GLOW_FRAG });
  blendAdd(m);
  m.depthTest = false;
  const mesh = new THREE.Mesh(new THREE.PlaneGeometry(1, 1), m);
  mesh.frustumCulled = false;
  mesh.renderOrder = order;
  mesh.visible = false;
  scene.add(mesh);
  return { mesh: mesh, u: u };
}
function buildFX() {
  G.fxImpact = makeGlow([1.0, 0.82, 0.55], 20);
  G.fxSnip = makeGlow([0.62, 0.80, 1.0], 21);
  G.fxFront = makeGlow([0.55, 0.78, 1.0], 22);
  G.fxBurst = makeGlow([0.78, 0.90, 1.0], 23);
  G.fxImpact.mesh.position.set(G.contactX + 0.02, G.contactY, 0.1);
  G.fxSnip.mesh.position.copy(SP.pCut).add(new THREE.Vector3(0, 0, 0.1));
  G.fxBurst.mesh.position.copy(SP.bulbCenter).add(new THREE.Vector3(0, 0, 0.2));
  /* shock cone quad: uv.x = 0 at the nose, growing backwards (+X) */
  G.coneU = { uInt: { value: 0 } };
  const cm = new THREE.ShaderMaterial({ uniforms: G.coneU, vertexShader: CONE_VERT, fragmentShader: CONE_FRAG });
  blendAdd(cm);
  cm.depthTest = false;
  G.cone = new THREE.Mesh(new THREE.PlaneGeometry(1, 1), cm);
  G.cone.scale.set(2.6, 1.7, 1);
  G.cone.frustumCulled = false;
  G.cone.renderOrder = 19;
  scene.add(G.cone);
}

/* 4k. Camera framing (fixed lens, locked on the Z axis; distance adapts to the aspect) */
function fitCamera() {
  const b = SP.bbox, pad = 0.06;
  const w = (b.x1 - b.x0) + 2 * pad, h = (b.y1 - b.y0) + 2 * pad;
  const cx = (b.x0 + b.x1) / 2, cy = (b.y0 + b.y1) / 2;
  const tanH = Math.tan(deg(FOV_DEG / 2));
  const dH = (h / 0.70) / (2 * tanH);
  const dW = (w / 0.70) / (2 * tanH * camera.aspect);
  const dist = Math.max(dH, dW);
  camera.position.set(cx, cy, dist);
  camera.rotation.set(0, 0, 0);
  camera.updateProjectionMatrix();
}

function applySize(w, h) {
  if (!gfxOK) return;
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.setSize(w, h, false);
  camera.aspect = w / h;
  fitCamera();
  G.dustU.uViewScale.value = h / (2 * Math.tan(deg(FOV_DEG / 2)));
  G.dustU.uPx.value = renderer.getPixelRatio();
  needsRender = true;
}

function initGraphics() {
  renderer = new THREE.WebGLRenderer({ canvas: document.getElementById('stage'), antialias: true, alpha: true });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.setSize(window.innerWidth, window.innerHeight, false);
  renderer.outputEncoding = THREE.sRGBEncoding;
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.05;
  renderer.setClearColor(0x000000, 0);
  scene = new THREE.Scene();
  camera = new THREE.PerspectiveCamera(FOV_DEG, window.innerWidth / window.innerHeight, 0.1, 120);

  resetRng();                                  // seed 42: all procedural data below is drawn in a fixed order
  envTex = buildEnvTexture();
  scene.environment = envTex;
  SP = buildSpine();
  buildLights();
  buildGlass();
  buildClamp();
  buildNippers();
  buildBullet();
  buildSpall();
  buildShards();
  buildDust();
  buildFX();
  gfxOK = true;
  applySize(window.innerWidth, window.innerHeight);
}

