/* ------------------------------------------------------------------ *
 * 5. renderAt(simTime): the whole visible state is a pure function of t
 * ------------------------------------------------------------------ */
function bulbPush(t) {
  const tau = t - T_IMPACT;
  if (tau <= 0) return 0;
  return 0.05 * Math.exp(-tau / 0.9) * Math.sin(Math.PI * 2 * 1.6 * tau);
}

function renderAt(tIn) {
  if (!gfxOK) return;
  const t = clamp(+tIn || 0, 0, DURATION);
  const tau = t - T_IMPACT;
  const push = bulbPush(t);

  /* glass */
  const U = G.glassU;
  const frontS = 1 - (t - T_FRONT_A) / (T_FRONT_B - T_FRONT_A);
  U.uTime.value = t;
  U.uFront.value = t < T_SNIP ? 3.0 : Math.min(frontS, SP.S_CUT + 0.004);
  U.uSnip.value = t >= T_SNIP ? 1 : 0;
  U.uNuc.value = sstep(T_SNIP, T_FRONT_A + 0.05, t);
  const pk = clamp((t - T_PULSE_A) / (T_PULSE_B - T_PULSE_A), 0, 1);
  const pulse = (t >= T_PULSE_A && t <= T_PULSE_B) ? Math.pow(Math.sin(Math.PI * pk), 2) : 0;
  U.uPulse.value = pulse;
  U.uStress.value = 0.26 + 0.44 * pulse;
  U.uRing.value = tau > 0 ? Math.exp(-tau / 0.8) : 0;
  U.uImpactT.value = tau;
  U.uPush.value = push;

  /* shards / dust */
  G.shardU.uTime.value = t;
  G.dustU.uTime.value = t;

  /* bullet + spall */
  const cx = G.contactX - (tau > 0 ? push : 0);
  G.bullet.position.set(tau <= 0 ? G.contactX + V_BULLET * (-tau) : cx, G.contactY, 0);
  G.bullet.visible = tau < 1.4;
  G.bulletU.uTau.value = tau;
  G.spallU.uTau.value = tau;
  G.spallU.uContact.value.set(cx, G.contactY, 0);

  /* supersonic bow-shock V attached to the flying nose; collapses on contact */
  const noseX = G.contactX + V_BULLET * Math.max(-tau, 0);
  G.cone.position.set(noseX + 1.3, G.contactY, 0.02);
  G.coneU.uInt.value = 1 - sstep(T_IMPACT - 0.02, T_IMPACT + 0.05, t);
  G.cone.visible = G.coneU.uInt.value > 0.002;

  /* nippers: approach, close, snip, retreat */
  const beta = jawBeta(t);
  G.armA.rotation.z = beta;
  G.armB.rotation.z = -beta;
  const off = -0.10 * (1 - sstep(T_PULSE_A, T_TOUCH, t)) - 2.6 * sstep(4.9, 5.9, t);
  G.tool.position.copy(G.pivot).addScaledVector(G.uDir, off);

  /* flashes and glows */
  const fi = tau < 0 ? 0 : Math.exp(-tau / 0.07) * 1.5 + 0.35 * Math.exp(-tau / 0.30);
  setGlow(G.fxImpact, fi, 0.9 + 0.8 * Math.min(tau, 0.3) / 0.3, 0.25 * Math.exp(-Math.max(tau, 0) / 0.2), 0, 0);
  const ts = t - T_SNIP;
  const fs = ts < 0 ? 0 : (1.6 * Math.exp(-Math.pow((ts - 0.07) / 0.07, 2)) + 0.55 * Math.exp(-ts / 0.30)) * sstep(0, 0.012, ts);
  setGlow(G.fxSnip, fs, 0.55 + 1.2 * Math.exp(-ts / 0.2), 0.9 * Math.exp(-Math.max(ts, 0) / 0.18), 0, 0);
  const wf = (t >= T_FRONT_A && t <= T_FRONT_B + 0.15) ? sstep(T_FRONT_A, T_FRONT_A + 0.12, t) * (1 - sstep(T_FRONT_B, T_FRONT_B + 0.15, t)) : 0;
  const fp = SP.posAtA(clamp(frontS, 0, 1) * SP.L, G.tmpV || (G.tmpV = new THREE.Vector3()));
  G.fxFront.mesh.position.set(fp.x, fp.y, fp.z + 0.15);
  setGlow(G.fxFront, wf * 0.75, 0.55, 0.15, 0, 0);
  G.frontLight.position.set(fp.x, fp.y, fp.z + 1.0);
  G.frontLight.intensity = wf * 4.5;
  const tb = t - T_BURST;
  const fb = tb < -0.12 ? 0 : (1.8 * Math.exp(-Math.pow((tb - 0.06) / 0.10, 2)) + 0.35 * Math.exp(-Math.max(tb, 0) / 0.45)) * sstep(-0.12, 0.02, tb);
  setGlow(G.fxBurst, fb, 1.3 + 3.0 * Math.max(tb, 0) * 0.5, 0, Math.max(tb, 0) * 2.6, 0.9 * Math.exp(-Math.max(tb, 0) / 0.55) * sstep(0, 0.03, tb));

  renderer.render(scene, camera);
  needsRender = false;
}

function setGlow(fx, intensity, size, streak, ringR, ringI) {
  fx.mesh.visible = intensity > 0.002 || ringI > 0.002;
  fx.u.uInt.value = intensity;
  fx.u.uSize.value = size;
  fx.u.uStreak.value = streak;
  fx.u.uRingR.value = clamp(ringR * 0.25, 0.0, 0.98) ;
  fx.u.uRingW.value = 0.05;
  fx.u.uRingI.value = ringI;
}

/* ------------------------------------------------------------------ *
 * 6. Playback state machine and controls
 * ------------------------------------------------------------------ */
function showCountdown(n) {
  elCountdown.style.display = 'block';
  elCountdown.textContent = String(n);
}
function hideCountdown() {
  elCountdown.style.display = 'none';
  elCountdown.textContent = '';
}
function setPlayingIcons(playing) {
  elIconPause.style.display = playing ? '' : 'none';
  elIconPlay.style.display = playing ? 'none' : '';
  elToggle.setAttribute('aria-label', playing ? 'Pause' : 'Play');
}
function setSpeed(pill) {
  playbackSpeed = parseFloat(pill.getAttribute('data-speed'));
  elPills.forEach(function (p) {
    const on = p === pill;
    p.classList.toggle('is-active', on);
    p.setAttribute('aria-checked', on ? 'true' : 'false');
  });
}

function doRefire() {
  hideCountdown();
  simTime = 0;
  elScrubber.value = '0';
  countdownElapsed = 0;
  holdElapsed = 0;
  state = 'REFIRE_HOLD';
  setPlayingIcons(true);
  renderAt(0);
}
function doToggle() {
  if (state === 'PLAYING') {
    state = 'PAUSED'; setPlayingIcons(false);
  } else if (state === 'COUNTDOWN' || state === 'REFIRE_HOLD') {
    hideCountdown();
    simTime = 0; elScrubber.value = '0';
    state = 'PAUSED'; setPlayingIcons(false);
    renderAt(0);
  } else if (state === 'PAUSED') {
    state = 'PLAYING'; setPlayingIcons(true);
  } else if (state === 'ENDED') {
    hideCountdown();
    simTime = 0; elScrubber.value = '0';
    state = 'PLAYING'; setPlayingIcons(true);
    renderAt(0);
  }
}
function doScrub() {
  if (state === 'COUNTDOWN' || state === 'REFIRE_HOLD') hideCountdown();
  simTime = clamp(parseFloat(elScrubber.value) || 0, 0, DURATION);
  state = 'PAUSED';
  setPlayingIcons(false);
  renderAt(simTime);
}

function frame(ts) {
  requestAnimationFrame(frame);
  let rawDt = lastTs === null ? 0 : (ts - lastTs) / 1000;
  lastTs = ts;
  if (!(rawDt >= 0)) rawDt = 0;
  const dt = Math.min(rawDt, 0.1);

  if (state === 'COUNTDOWN') {
    countdownElapsed += dt;
    if (countdownElapsed >= 3.0) {
      hideCountdown();
      state = 'PLAYING';
    } else {
      showCountdown(3 - Math.floor(countdownElapsed));
    }
  } else if (state === 'REFIRE_HOLD') {
    holdElapsed += dt;
    if (holdElapsed >= 1.0) state = 'PLAYING';
  } else if (state === 'PLAYING') {
    simTime = Math.min(DURATION, simTime + dt * playbackSpeed);
    elScrubber.value = simTime.toFixed(3);
    renderAt(simTime);
    if (simTime >= DURATION) {
      simTime = DURATION;
      elScrubber.value = DURATION.toFixed(3);
      state = 'ENDED';
      setPlayingIcons(false);
    }
    return;
  }
  if (needsRender) renderAt(simTime);
}

elToggle.addEventListener('click', doToggle);
elRefire.addEventListener('click', doRefire);
elScrubber.addEventListener('input', doScrub);
elPills.forEach(function (p) { p.addEventListener('click', function () { setSpeed(p); }); });
window.addEventListener('resize', function () {
  applySize(window.innerWidth, window.innerHeight);
  renderAt(simTime);
});

/* ------------------------------------------------------------------ *
 * 7. Boot: build, draw the resting scene (simTime = 0), then start the
 *    wall-clock countdown on the first animation frame after that.
 * ------------------------------------------------------------------ */
try {
  if (typeof THREE === 'undefined') throw new Error('three.js failed to load');
  initGraphics();
} catch (err) {
  gfxOK = false;
  console.error('Graphics initialisation failed:', err);
}
showCountdown(3);
elScrubber.value = '0';
setPlayingIcons(true);
renderAt(0);
