626	  vec3 p = aA.xyz + particleOffset( aB.w, aB.xyz, aC.x, aC.y, aC.z, ${T_BURST.toFixed(2)}, uTime );
627	  vec4 mv = modelViewMatrix * vec4( p, 1.0 );
628	  gl_Position = projectionMatrix * mv;
629	  float grow = smoothstep( 0.0, 0.25, age );
630	  gl_PointSize = max( 1.0, aA.w * ( 0.55 + 0.45 * grow ) * uViewScale * uPx / max( - mv.z, 0.1 ) );
631	  float tw = 0.55 + 0.45 * sin( uTime * ( 3.0 + 9.0 * aC.w ) + aC.w * 60.0 );
632	  vAlpha = smoothstep( 0.0, 0.18, age ) * tw * ( 0.55 + 0.45 * aC.w );
633	  vSeed = aC.w;
634	  if ( age < 0.0 ) gl_Position = vec4( 2.0, 2.0, 2.0, 1.0 );
635	}
