637	const DUST_FRAG = `
638	varying float vAlpha;
639	varying float vSeed;
640	void main() {
641	  vec2 p = gl_PointCoord - 0.5;
642	  float r2 = dot( p, p ) * 4.0;
643	  float a = 1.0 - smoothstep( 0.0, 1.0, r2 );
644	  a *= a;
