675	  float ring = exp( - pow( ( r - uRingR ) / max( uRingW, 1e-3 ), 2.0 ) ) * uRingI;
676	  float I = ( core + halo + streak ) * uInt + ring;
677	  I *= 1.0 - smoothstep( 0.80, 1.0, r );
