744	/* 4b. Spine: bulb (s = 0) -> neck -> helical tail tip (s = 1), arc-length parameterised */
745	const R_J_ANGLE = deg(130);
746	const A_JUNC = BULB_R * (1 - Math.cos(R_J_ANGLE));
747	const R_JUNC = BULB_R * Math.sin(R_J_ANGLE);
748	const R_TAIL = 0.026;
749	const LAMBDA = (R_JUNC - R_TAIL) / Math.tan(deg(40));
750	const CAP_LEN = 0.045;
751	
752	function radiusAt(a, L) {
753	  if (a <= 0) return 0;
754	  let r;
755	  if (a < A_JUNC) r = Math.sqrt(Math.max(0, BULB_R * BULB_R - (a - BULB_R) * (a - BULB_R)));
756	  else r = R_TAIL + (R_JUNC - R_TAIL) * Math.exp(-(a - A_JUNC) / LAMBDA);
757	  const aCap = L - CAP_LEN;
758	  if (a > aCap) { const q = (a - aCap) / CAP_LEN; r *= Math.sqrt(Math.max(0, 1 - q * q)); }
759	  return r;
760	}
761	
762	function buildSpine() {
763	  const V3 = THREE.Vector3;
764	  const ctrl = [
765	    new V3(0.10, -2.20, 0), new V3(0.10, -1.58, 0), new V3(0.15, -0.88, 0), new V3(0.36, -0.12, 0),
766	    new V3(0.30, 0.70, 0), new V3(-0.08, 1.32, 0), new V3(-0.55, 1.74, 0), new V3(-1.12, 1.98, 0)
767	  ];
768	  const base = new THREE.CatmullRomCurve3(ctrl, false, 'centripetal');
769	  const M = 2400;
770	  const px = new Float64Array(M + 1), py = new Float64Array(M + 1), pz = new Float64Array(M + 1);
771	  const U0 = 0.50, U1 = 0.905, TURNS = 2.5, HAMP = 0.15;
772	  for (let i = 0; i <= M; i++) {
773	    const u = i / M;
774	    const p = base.getPoint(u);
775	    const tg = base.getTangent(u);
776	    let nx = -tg.y, ny = tg.x;
777	    const nl = Math.hypot(nx, ny) || 1; nx /= nl; ny /= nl;
778	    const env = sstep(U0, U0 + 0.10, u) * (1 - sstep(U1 - 0.09, U1, u));
779	    const ph = Math.PI * 2 * TURNS * (u - U0) / (U1 - U0);
780	    const off = HAMP * env;
781	    px[i] = p.x + nx * off * Math.cos(ph);
782	    py[i] = p.y + ny * off * Math.cos(ph);
783	    pz[i] = off * Math.sin(ph);
784	  }
785	  const cum = new Float64Array(M + 1);
786	  for (let i = 1; i <= M; i++) cum[i] = cum[i - 1] + Math.hypot(px[i] - px[i - 1], py[i] - py[i - 1], pz[i] - pz[i - 1]);
787	  const L = cum[M];
788	
789	  const S = { L: L };
790	  S.posAtA = function (a, out) {
791	    a = clamp(a, 0, L);
792	    let lo = 0, hi = M;
793	    while (hi - lo > 1) { const mid = (lo + hi) >> 1; if (cum[mid] <= a) lo = mid; else hi = mid; }
794	    const seg = cum[hi] - cum[lo];
795	    const f = seg > 0 ? (a - cum[lo]) / seg : 0;
796	    return out.set(lerp(px[lo], px[hi], f), lerp(py[lo], py[hi], f), lerp(pz[lo], pz[hi], f));
797	  };
798	  S.tanAtA = function (a, out) {
799	    const e = 0.004;
800	    const p0 = S.posAtA(Math.max(0, a - e), new V3()), p1 = S.posAtA(Math.min(L, a + e), new V3());
801	    return out.copy(p1).sub(p0).normalize();
802	  };
803	
804	  /* ring list: dome rings (uniform polar angle), neck rings (uniform arc length), tip-cap rings */
805	  const ringA = [], domeK = 34;
806	  for (let k = 0; k <= domeK; k++) ringA.push(BULB_R * (1 - Math.cos(R_J_ANGLE * k / domeK)));
807	  const aEnd = L - CAP_LEN, nNeck = 300;
808	  for (let k = 1; k <= nNeck; k++) ringA.push(A_JUNC + (aEnd - A_JUNC) * k / nNeck);
809	  const nCap = 8;
810	  for (let k = 1; k <= nCap; k++) ringA.push(aEnd + CAP_LEN * Math.sin(Math.PI / 2 * k / nCap));
811	  const NR = ringA.length;
812	  S.ringA = ringA; S.nDome = domeK + 1;
813	  S.ringS = ringA.map(a => a / L);
814	  S.ringR = ringA.map(a => radiusAt(a, L));
815	  S.ringC = []; S.ringT = []; S.ringN = []; S.ringB = [];
816	  for (let i = 0; i < NR; i++) {
817	    S.ringC.push(S.posAtA(ringA[i], new V3()));
818	    S.ringT.push(S.tanAtA(ringA[i], new V3()));
819	  }
820	  /* rotation-minimising frames (parallel transport) */
821	  let Nprev = new V3(1, 0, 0);
822	  for (let i = 0; i < NR; i++) {
823	    const T = S.ringT[i];
824	    const N = Nprev.clone().addScaledVector(T, -Nprev.dot(T)).normalize();
825	    S.ringN.push(N); S.ringB.push(new V3().crossVectors(T, N).normalize());
826	    Nprev = N;
827	  }
828	
829	  S.frameAt = function (s, out) {
830	    s = clamp(s, 0, 1);
831	    const SS = S.ringS; let lo = 0, hi = SS.length - 1;
832	    while (hi - lo > 1) { const mid = (lo + hi) >> 1; if (SS[mid] <= s) lo = mid; else hi = mid; }
833	    const f = (s - SS[lo]) / Math.max(1e-9, SS[hi] - SS[lo]);
834	    out.C.copy(S.ringC[lo]).lerp(S.ringC[hi], f);
835	    out.T.copy(S.ringT[lo]).lerp(S.ringT[hi], f).normalize();
836	    out.N.copy(S.ringN[lo]).lerp(S.ringN[hi], f);
837	    out.N.addScaledVector(out.T, -out.N.dot(out.T)).normalize();
838	    out.B.crossVectors(out.T, out.N);
839	    out.r = lerp(S.ringR[lo], S.ringR[hi], f);
840	    return out;
841	  };
842	
843	  /* sampling density for shards / dust (volume-ish, with a floor so the thin tail is populated) */
844	  S.makeCdf = function (floor) {
845	    const cdf = new Float64Array(NR); let acc = 0;
846	    for (let i = 1; i < NR; i++) {
847	      const r = 0.5 * (S.ringR[i] + S.ringR[i - 1]);
848	      acc += (Math.pow(r, 1.6) + floor) * (ringA[i] - ringA[i - 1]);
849	      cdf[i] = acc;
850	    }
851	    for (let i = 0; i < NR; i++) cdf[i] /= acc;
852	    return function (u) {
853	      let lo = 0, hi = NR - 1;
854	      while (hi - lo > 1) { const mid = (lo + hi) >> 1; if (cdf[mid] <= u) lo = mid; else hi = mid; }
855	      const f = (u - cdf[lo]) / Math.max(1e-9, cdf[hi] - cdf[lo]);
856	      return lerp(S.ringS[lo], S.ringS[hi], f);
857	    };
858	  };
859

860	  /* landmarks */
861	  S.A_CUT = L - 0.16;
862	  S.S_CUT = S.A_CUT / L;
863	  S.A_CLAMP = 1.78;
864	  S.S_CLAMP = S.A_CLAMP / L;
865	  S.bulbCenter = S.posAtA(BULB_R, new V3());
866	  S.pCut = S.posAtA(S.A_CUT, new V3());
867	  S.tCut = S.tanAtA(S.A_CUT, new V3());
868	  /* bounding box of the glass */
869	  let x0 = 1e9, x1 = -1e9, y0 = 1e9, y1 = -1e9;
870	  for (let i = 0; i < NR; i++) {
871	    const c = S.ringC[i], r = S.ringR[i];
872	    x0 = Math.min(x0, c.x - r); x1 = Math.max(x1, c.x + r);
873	    y0 = Math.min(y0, c.y - r); y1 = Math.max(y1, c.y + r);
874	  }
875	  S.bbox = { x0: x0, x1: x1, y0: y0, y1: y1 };
876	  return S;
877	}
