914	function buildGlass() {
915	  const NS = 48, NR = SP.ringA.length, nV = NR * (NS + 1);
916	  const pos = new Float32Array(nV * 3), nor = new Float32Array(nV * 3);
917	  const aS = new Float32Array(nV), aPhi = new Float32Array(nV), aRad = new Float32Array(nV);
918	  const index = [];
919	  for (let i = 0; i < NR; i++) {
920	    const C = SP.ringC[i], T = SP.ringT[i], N = SP.ringN[i], B = SP.ringB[i], r = SP.ringR[i];
921	    const i0 = Math.max(0, i - 1), i1 = Math.min(NR - 1, i + 1);
922	    const rp = (SP.ringR[i1] - SP.ringR[i0]) / Math.max(1e-6, SP.ringA[i1] - SP.ringA[i0]);
923	    const isDome = i < SP.nDome;
924	    const phi = isDome ? R_J_ANGLE * i / (SP.nDome - 1) : 0;
925	    for (let j = 0; j <= NS; j++) {
926	      const th = j / NS * Math.PI * 2, c = Math.cos(th), s = Math.sin(th);
927	      const rx = N.x * c + B.x * s, ry = N.y * c + B.y * s, rz = N.z * c + B.z * s;
928	      const k = (i * (NS + 1) + j);
929	      pos[k * 3] = C.x + rx * r; pos[k * 3 + 1] = C.y + ry * r; pos[k * 3 + 2] = C.z + rz * r;
930	      let nx, ny, nz;
931	      if (i === 0) { nx = -T.x; ny = -T.y; nz = -T.z; }
932	      else if (i === NR - 1) { nx = T.x; ny = T.y; nz = T.z; }
933	      else if (isDome) {
934	        const sp = Math.sin(phi), cp = Math.cos(phi);
935	        nx = sp * rx - cp * T.x; ny = sp * ry - cp * T.y; nz = sp * rz - cp * T.z;
936	      } else {
937	        const inv = 1 / Math.sqrt(1 + rp * rp);
938	        nx = (rx - T.x * rp) * inv; ny = (ry - T.y * rp) * inv; nz = (rz - T.z * rp) * inv;
939	      }
940	      nor[k * 3] = nx; nor[k * 3 + 1] = ny; nor[k * 3 + 2] = nz;
941	      aS[k] = SP.ringS[i]; aPhi[k] = th; aRad[k] = r;
942	    }
943	  }
944	  for (let i = 0; i < NR - 1; i++) {
945	    for (let j = 0; j < NS; j++) {
946	      const a = i * (NS + 1) + j, b = (i + 1) * (NS + 1) + j, c = a + 1, d = b + 1;
947	      index.push(a, c, b, b, c, d);
948	    }
949	  }
950	  const geo = new THREE.BufferGeometry();
951	  geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
952	  geo.setAttribute('normal', new THREE.BufferAttribute(nor, 3));
953	  geo.setAttribute('aS', new THREE.BufferAttribute(aS, 1));
954	  geo.setAttribute('aPhi', new THREE.BufferAttribute(aPhi, 1));
955	  geo.setAttribute('aRad', new THREE.BufferAttribute(aRad, 1));
956	  geo.setIndex(index);
957	
958	  G.glassU = {
959	    uTime: { value: 0 }, uFront: { value: 3 }, uCutS: { value: SP.S_CUT }, uSnip: { value: 0 }, uNuc: { value: 0 },
960	    uStress: { value: 0.5 }, uPulse: { value: 0 }, uRing: { value: 0 }, uImpactT: { value: -1 },
961	    uImpactPos: { value: new THREE.Vector3(SP.bulbCenter.x + BULB_R, SP.bulbCenter.y, 0) },
962	    uTransGain: { value: 0.85 }, uPush: { value: 0 }, uClampS: { value: SP.S_CLAMP }
963	  };
964	  G.glassBack = new THREE.Mesh(geo, makeGlassMaterial(true));
965	  G.glassFront = new THREE.Mesh(geo, makeGlassMaterial(false));
966	  G.glassBack.renderOrder = 1; G.glassFront.renderOrder = 2;
967	  G.glassBack.frustumCulled = false; G.glassFront.frustumCulled = false;
968	  scene.add(G.glassBack); scene.add(G.glassFront);
969	}
