1106	    return lerp(BETA_OPEN, touch, k);
1107	  }
1108	  if (t < T_SNIP) {
1109	    const k = (t - T_TOUCH) / (T_SNIP - T_TOUCH);
1110	    return lerp(touch, BETA_T - deg(0.35), k * k);
1111	  }
1112	  return lerp(BETA_T - deg(0.35), closed, sstep(T_SNIP, T_SNIP + 0.09, t));
1113	}
