1116	function buildBullet() {
1117	  const BS = 1.14;                                  // overall bullet scale
1118	  const R0 = 0.17 * BS, LB = 1.0 * BS, AN = 0.58 * BS, A_CAP = 0.60 * BS, CH = 0.06 * BS;
1119	  const NOSE = 40, CYL = 14, CHAM = 4;
1120	  const P0 = [];
1121	  for (let i = 0; i <= NOSE; i++) {
1122	    const a = AN * Math.pow(i / NOSE, 1.25), uu = a / AN;
1123	    P0.push([a, R0 * Math.sin(0.5 * Math.PI * Math.pow(uu, 0.85))]);
1124	  }
1125	  for (let i = 1; i <= CYL; i++) P0.push([AN + (LB - CH - AN) * i / CYL, R0]);
1126	  for (let i = 1; i <= CHAM; i++) { const q = i / CHAM; P0.push([LB - CH + CH * q, R0 * (1 - 0.14 * q)]); }
1127	  P0.push([LB, R0 * 0.55]); P0.push([LB, 0.0]);
1128	  const N = P0.length, iCap = NOSE;
1129	
1130	  /* target "mushroom" profile with the same parameterisation */
1131	  const RM = 0.46 * BS, TR = 0.10 * BS, CUP = 0.7, RG = BULB_R, stemR = R0 * 1.12, STEM_K = 0.80;
1132	  const face = (rho) => -CUP * (RG - Math.sqrt(Math.max(0, RG * RG - rho * rho)));
1133	  const rhoF = RM - TR / 2, UF = 0.55, UR = 0.80;
1134	  const P1 = [];
1135	  for (let i = 0; i < N; i++) {
1136	    const a = P0[i][0], rho = P0[i][1];
1137	    if (i <= iCap) {
1138	      const u = i / iCap;
1139	      if (u <= UF) { const r = rhoF * (u / UF); P1.push([face(r), r]); }
1140	      else if (u <= UR) {
1141	        const psi = Math.PI * (u - UF) / (UR - UF);
1142	        P1.push([face(rhoF) + TR / 2 * (1 - Math.cos(psi)), rhoF + TR / 2 * Math.sin(psi)]);
1143	      } else {
1144	        const r = rhoF + (stemR - rhoF) * ((u - UR) / (1 - UR));
1145	        P1.push([face(r) + TR, r]);
1146	      }
1147	    } else {
1148	      const aCapEnd = face(stemR) + TR;
1149	      P1.push([aCapEnd + (a - A_CAP) * STEM_K, rho * 1.12 * (1 + 0.14 * Math.exp(-(a - A_CAP) / 0.10))]);
1150	    }
1151	  }
1152	  function profNormals(P) {
