1154	    for (let i = 0; i < P.length; i++) {
1155	      if (i === 0) { out.push([-1, 0]); continue; }
1156	      if (i === P.length - 1) { out.push([1, 0]); continue; }
1157	      let da = P[i + 1][0] - P[i - 1][0], dr = P[i + 1][1] - P[i - 1][1];
1158	      const l = Math.hypot(da, dr) || 1; da /= l; dr /= l;
