1165	  const NSEG = 56, nV = N * (NSEG + 1);
1166	  const pos = new Float32Array(nV * 3), nor = new Float32Array(nV * 3), col = new Float32Array(nV * 3);
1167	  const aP1 = new Float32Array(nV * 2), aN1 = new Float32Array(nV * 2), aST = new Float32Array(nV * 2);
1168	  const lead = [0.40, 0.42, 0.47], copper = [0.84, 0.38, 0.15];
1169	  for (let i = 0; i < N; i++) {
1170	    const cu = sstep(0.54, 0.64, P0[i][0]);
1171	    for (let j = 0; j <= NSEG; j++) {
1172	      const th = j / NSEG * Math.PI * 2, c = Math.cos(th), s = Math.sin(th);
1173	      const k = i * (NSEG + 1) + j;
1174	      pos[k * 3] = P0[i][0]; pos[k * 3 + 1] = P0[i][1] * c; pos[k * 3 + 2] = P0[i][1] * s;
