1180	    }
1181	  }
1182	  const index = [];
1183	  for (let i = 0; i < N - 1; i++) for (let j = 0; j < NSEG; j++) {
1184	    const a = i * (NSEG + 1) + j, b = (i + 1) * (NSEG + 1) + j, c = a + 1, d = b + 1;
1185	    index.push(a, c, b, b, c, d);              // outward-facing, same convention as the glass
1186	  }
1187	  const geo = new THREE.BufferGeometry();
1188	  geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
1189	  geo.setAttribute('normal', new THREE.BufferAttribute(nor, 3));
1190	  geo.setAttribute('color', new THREE.BufferAttribute(col, 3));
1191	  geo.setAttribute('aP1', new THREE.BufferAttribute(aP1, 2));
1192	  geo.setAttribute('aN1', new THREE.BufferAttribute(aN1, 2));
1193	  geo.setAttribute('aST', new THREE.BufferAttribute(aST, 2));
