1198	  m.onBeforeCompile = function (shader) {
1199	    Object.assign(shader.uniforms, G.bulletU);
1200	    let v = shader.vertexShader, f = shader.fragmentShader;
1201	    v = patch(v, '#include <common>', '#include <common>\n' + BULLET_VERT_PARS, 'bullet vert pars');
1202	    v = patch(v, '#include <beginnormal_vertex>', BULLET_VERT_NORMAL, 'bullet vert normal');
1203	    v = patch(v, '#include <begin_vertex>', BULLET_VERT_BEGIN, 'bullet vert begin');
1204	    f = patch(f, '#include <common>', '#include <common>\n' + BULLET_FRAG_PARS, 'bullet frag pars');
1205	    f = patch(f, '#include <clipping_planes_fragment>', '#include <clipping_planes_fragment>\n' + BULLET_FRAG_PROLOGUE, 'bullet frag prologue');
1206	    f = patch(f, '#include <emissivemap_fragment>', '#include <emissivemap_fragment>\ntotalEmissiveRadiance += vec3( 1.0, 0.46, 0.16 ) * dissEdge * 0.9;', 'bullet frag emissive');
