1208	  };
1209	  m.customProgramCacheKey = function () { return 'prd-bullet'; };
1210	  const mesh = new THREE.Mesh(geo, m);
1211	  mesh.frustumCulled = false;
1212	  const grp = new THREE.Group();
1213	  grp.add(mesh);
1214	  scene.add(grp);
1215	  G.bullet = grp;
1216	  G.contactX = SP.bulbCenter.x + BULB_R;
1217	  G.contactY = SP.bulbCenter.y;
1218	}
