1281	    const k2 = (k + 1) % 3;
1282	    tris.push([A[k], B[k], B[k2]], [A[k], B[k2], A[k2]], [tL, A[k2], A[k]], [tR, B[k], B[k2]]);
1283	  }
1284	  const pos = [], nor = [];
1285	  tris.forEach(t => {
1286	    const e1 = [t[1][0] - t[0][0], t[1][1] - t[0][1], t[1][2] - t[0][2]], e2 = [t[2][0] - t[0][0], t[2][1] - t[0][1], t[2][2] - t[0][2]];
