import sys, json, os, re

# usage: mk2.py <scenario.js> <out.html> [--nothree] [--cfg '{json}']
# Reads the deliverable, swaps the CDN tag for local three.min.js (or a missing file with --nothree),
# overrides requestAnimationFrame so the scenario can step a fake clock, and appends the scenario JS.
WORK = '/private/tmp/pcd-sbx-claude-sonnet-5.5-y10vo3xz/work/index.html'
scen = sys.argv[1]
out = sys.argv[2]
nothree = '--nothree' in sys.argv
cfg = {}
if '--cfg' in sys.argv:
    cfg = json.loads(sys.argv[sys.argv.index('--cfg') + 1])
norafs = '--realraf' in sys.argv

src = open(WORK, encoding='utf-8').read()
CDN = '<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>'
assert CDN in src, 'CDN tag not found'

PRE = r'''<script>
window.__L = function (m) { try { new Image().src = 'http://127.0.0.1:8765/log?m=' + encodeURIComponent(String(m).slice(0, 1800)) + '&r=' + Math.random(); } catch (e) {} };
(function () {
  function relay(tag, args) {
    var s = Array.prototype.map.call(args, function (a) { try { return typeof a === 'string' ? a : JSON.stringify(a); } catch (e) { return String(a); } }).join(' ');
    var lines = s.split('\n').filter(function (l) { return l.length < 400; }).slice(0, 12);
    lines.forEach(function (l) { window.__L(tag + ' ' + l); });
  }
  var oe = console.error, ow = console.warn;
  console.error = function () { relay('[console.error]', arguments); oe.apply(console, arguments); };
  console.warn = function () { relay('[console.warn]', arguments); ow.apply(console, arguments); };
  window.addEventListener('error', function (e) { window.__L('[window.onerror] ' + e.message + ' @' + (e.filename || '').split('/').pop() + ':' + e.lineno + ':' + e.colno); });
  window.addEventListener('unhandledrejection', function (e) { window.__L('[unhandledrejection] ' + e.reason); });
  RAFOVERRIDE
})();
</script>
'''
RAF = r'''window.__rafQ = [];
  window.requestAnimationFrame = function (cb) { window.__rafQ.push(cb); return window.__rafQ.length; };'''
PRE = PRE.replace('RAFOVERRIDE', '' if norafs else RAF)

CFG = 'window.CFG = ' + json.dumps(cfg) + ';'
body = open(scen, encoding='utf-8').read()
three = '<script src="three-missing-xyz.js"></script>' if nothree else '<script src="three.min.js"></script>'
html = src.replace(CDN, PRE + '<script>' + CFG + '</script>' + three)
idx = html.rfind('</body>')
html = html[:idx] + '<script>' + body + '</script>' + html[idx:]
open(out, 'w', encoding='utf-8').write(html)
print('wrote', out, len(html))

(function () {
  var fails = 0, n = 0;
  function check(name, cond, extra) { n++; if (!cond) fails++; __L((cond ? 'PASS ' : 'FAIL ') + name + (extra !== undefined ? '  [' + extra + ']' : '')); }
  function info(s) { __L('INFO ' + s); }
  var fakeNow = 700;
  function step(ms) { fakeNow += ms; var q = window.__rafQ; window.__rafQ = []; for (var i = 0; i < q.length; i++) q[i](fakeNow); }
  function run(sec, frameMs) { frameMs = frameMs || 16.667; var k = Math.round(sec * 1000 / frameMs); for (var i = 0; i < k; i++) step(frameMs); }
  var cd = document.getElementById('countdown'), sc = document.getElementById('scrubber'), tg = document.getElementById('btn-toggle'), rf = document.getElementById('btn-refire');
  var ip = document.getElementById('icon-pause'), ipl = document.getElementById('icon-play');
  var pills = Array.prototype.slice.call(document.querySelectorAll('.speed-pill'));
  function disp(el) { return getComputedStyle(el).display; }
  function vis(el) { return disp(el) !== 'none'; }
  function snap(tag) { return tag + ': state=' + state + ' sim=' + simTime.toFixed(4) + ' scrub=' + sc.value + ' cd=' + (vis(cd) ? ('"' + cd.textContent + '"') : 'hidden') + ' pause=' + vis(ip) + ' play=' + vis(ipl) + ' aria=' + tg.getAttribute('aria-label') + ' speed=' + playbackSpeed; }
  function resetToCountdown() { state = 'COUNTDOWN'; countdownElapsed = 0; holdElapsed = 0; lastTs = null; simTime = 0; sc.value = '0'; showCountdown(3); setPlayingIcons(true); }

  try {
    __L('--- logic A start ---');
    // ---------- A: initial DOM ----------
    check('A1 initial #countdown visible with "3"', vis(cd) && cd.textContent === '3', snap('init'));
    check('A2 initial scrubber "0", pause icon visible, aria Pause', sc.value === '0' && vis(ip) && !vis(ipl) && tg.getAttribute('aria-label') === 'Pause', snap('init'));
    check('A3 initial pill 1.0 active', pills[2].classList.contains('is-active') && pills[2].getAttribute('aria-checked') === 'true' && playbackSpeed === 1);
    check('A4 initial simTime 0, state COUNTDOWN', simTime === 0 && state === 'COUNTDOWN' && countdownElapsed === 0);
    step(16);
    check('A5 first rAF callback: countdownElapsed stays 0 (clock starts on first callback)', countdownElapsed === 0 && state === 'COUNTDOWN' && cd.textContent === '3', 'elapsed=' + countdownElapsed);
    step(16.667);
    check('A6 second callback advances by ~16.7 ms', Math.abs(countdownElapsed - 0.016667) < 1e-6, 'elapsed=' + countdownElapsed);

    // ---------- B: countdown cadence at several refresh rates ----------
    [8.3333, 16.6667, 33.3333, 6.9444, 100].forEach(function (ms) {
      resetToCountdown();
      step(ms); // first callback -> elapsed 0
      var T = 0, tTwo = null, tOne = null, tPlay = null, textBad = 0, hiddenBad = 0, simBad = 0, scrubBad = 0, guard = 0;
      var prev = '3';
      while (state === 'COUNTDOWN' && guard++ < 5000) {
        // invariants while COUNTDOWN
        var want = String(3 - Math.floor(countdownElapsed));
        if (cd.textContent !== want || cd.style.display !== 'block') textBad++;
        if (simTime !== 0) simBad++;
        if (sc.value !== '0') scrubBad++;
        step(ms); T += ms / 1000;
        if (state === 'COUNTDOWN') {
          if (cd.textContent === '2' && tTwo === null) tTwo = T;
          if (cd.textContent === '1' && tOne === null) tOne = T;
        } else { tPlay = T; }
      }
      var tol = ms / 1000 + 1e-6;
      check('B cadence ' + ms + 'ms: "2" at 1.0..1.0+dt, "1" at 2.0.., PLAYING at 3.0..', tTwo >= 1.0 - 1e-6 && tTwo <= 1.0 + tol + 1e-6 && tOne >= 2.0 - 1e-6 && tOne <= 2.0 + tol + 1e-6 && tPlay >= 3.0 - 1e-6 && tPlay <= 3.0 + tol + 1e-6, 'tTwo=' + (tTwo && tTwo.toFixed(4)) + ' tOne=' + (tOne && tOne.toFixed(4)) + ' tPlay=' + (tPlay && tPlay.toFixed(4)));
      check('B cadence ' + ms + 'ms: text==3-floor(elapsed) & display block each frame, simTime==0, scrub "0"', textBad === 0 && simBad === 0 && scrubBad === 0, 'textBad=' + textBad + ' simBad=' + simBad + ' scrubBad=' + scrubBad);
      check('B cadence ' + ms + 'ms: at hand-over: hidden (display none, text ""), PLAYING, simTime still 0', state === 'PLAYING' && cd.style.display === 'none' && cd.textContent === '' && simTime === 0, snap('handover') + ' inlineDisplay=' + cd.style.display);
      var before = simTime; step(ms);
      info('B cadence ' + ms + 'ms: first PLAYING frame advanced simTime by ' + (simTime - before).toFixed(5) + ' (dt=' + (ms / 1000).toFixed(5) + '; clamp 0.1)');
    });

    // ---------- C: clamp ----------
    resetToCountdown(); step(16); step(16.667);
    var e0 = countdownElapsed; step(5000);
    check('C1 COUNTDOWN dt clamped to 0.1 on a 5 s gap', Math.abs((countdownElapsed - e0) - 0.1) < 1e-9, 'delta=' + (countdownElapsed - e0));
    // speed selector must not affect countdown
    pills[0].click();
    resetToCountdown(); step(16); run(1.5);
    check('C2 countdown unaffected by 0.25x pill: "2" at ~1.5s', cd.textContent === '2', snap('speed0.25 @1.5'));
    run(1.6);
    check('C3 ... PLAYING after ~3.1s with 0.25x', state === 'PLAYING', snap('speed0.25 @3.1'));
    pills[2].click();

    // ---------- D: playing, speed, end ----------
    resetToCountdown(); step(16); run(3.2);
    check('D0 now PLAYING', state === 'PLAYING', snap('D0'));
    var s0 = simTime; var bad = 0;
    for (var i = 0; i < 60; i++) { step(16.667); if (sc.value !== simTime.toFixed(3)) bad++; }
    check('D1 PLAYING at 1x: +1.0 s per 60 frames; scrubber == toFixed(3) every frame', Math.abs((simTime - s0) - 1.0) < 0.002 && bad === 0, 'delta=' + (simTime - s0).toFixed(4) + ' bad=' + bad);
    [0.25, 0.5, 2.0].forEach(function (sp, idx) {
      pills[idx === 2 ? 3 : idx].click();
      check('D2 pill ' + sp + ' sets playbackSpeed & exclusive aria', playbackSpeed === sp && pills.filter(function (p) { return p.classList.contains('is-active'); }).length === 1 && pills.filter(function (p) { return p.getAttribute('aria-checked') === 'true'; }).length === 1 && pills[idx === 2 ? 3 : idx].getAttribute('aria-checked') === 'true');
      var a = simTime; if (state === 'PLAYING') { run(0.5); check('D3 speed ' + sp + ' rate', Math.abs((simTime - a) - 0.5 * sp) < 0.01, 'delta=' + (simTime - a).toFixed(4)); }
    });
    pills[3].click(); // 2x
    var guard2 = 0; var lastBefore = 0;
    while (state === 'PLAYING' && guard2++ < 2000) { lastBefore = simTime; step(16.667); }
    check('D4 reaches ENDED with simTime == 8 exactly', state === 'ENDED' && simTime === 8, snap('end'));
    check('D5 ENDED scrubber assigned "8.000" (reads back "' + sc.value + '")', parseFloat(sc.value) === 8);
    check('D6 ENDED icons: pause hidden, play shown, aria Play', !vis(ip) && vis(ipl) && tg.getAttribute('aria-label') === 'Play', snap('end'));
    check('D7 final render used t=8 (uTime)', G.glassU.uTime.value === 8, 'uTime=' + G.glassU.uTime.value);
    run(1.0);
    check('D8 ENDED holds (simTime stays 8)', state === 'ENDED' && simTime === 8);
    // ENDED -> toggle
    tg.click();
    check('D9 toggle in ENDED -> PLAYING, simTime 0, scrub "0", countdown hidden, pause icon, aria Pause', state === 'PLAYING' && simTime === 0 && sc.value === '0' && !vis(cd) && cd.textContent === '' && vis(ip) && !vis(ipl) && tg.getAttribute('aria-label') === 'Pause', snap('restart'));
    step(16.667);
    check('D10 next frame advances from 0', simTime > 0 && simTime < 0.1, snap('restart+1'));

